                await call('fees/' + key, 'PATCH', { companyId, itemId, feeItemId, delayMonths, amount, repeat, unit,...(debtCategory?{debtCategory,sourceItemIds}:{}), contractEvidenceId, notes, revision, effectiveOn: date(), enabled: !r.enabled, confirm: true }, crypto.randomUUID());
                await ctx.refresh();
